"""The load pipeline."""

from data.ingest.reader import read_trades


def run_load(path: str) -> int:
    """Read the trades at path and return their count."""
    rows = _read(path)
    return len(rows)


def _read(path: str) -> list[dict[str, str]]:
    """Read the trades at path."""
    return read_trades(path)
